import{_ as e,o as d,c as o,a4 as a}from"./chunks/framework.BMj-uaUw.js";const h=JSON.parse('{"title":"1. 为什么是 uni-app","description":"","frontmatter":{},"headers":[{"level":2,"title":"一个具体的场面","slug":"一个具体的场面","link":"#一个具体的场面","children":[]},{"level":2,"title":"三条路，选哪条","slug":"三条路-选哪条","link":"#三条路-选哪条","children":[]},{"level":2,"title":"uni-app 是怎么做到一套代码多端的","slug":"uni-app-是怎么做到一套代码多端的","link":"#uni-app-是怎么做到一套代码多端的","children":[]},{"level":2,"title":"先分清：uni-app 和 uni-app x 是两个东西","slug":"先分清-uni-app-和-uni-app-x-是两个东西","link":"#先分清-uni-app-和-uni-app-x-是两个东西","children":[]},{"level":2,"title":"和管理端的 Vue 项目差在哪","slug":"和管理端的-vue-项目差在哪","link":"#和管理端的-vue-项目差在哪","children":[]},{"level":2,"title":"什么时候不该用 uni-app","slug":"什么时候不该用-uni-app","link":"#什么时候不该用-uni-app","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"常见坑","slug":"常见坑","link":"#常见坑","children":[]},{"level":2,"title":"课后练习","slug":"课后练习","link":"#课后练习","children":[]}],"relativePath":"mobile/01-why-uniapp.md","filePath":"mobile/01-why-uniapp.md","lastUpdated":1789500881000}'),n={name:"mobile/01-why-uniapp.md"};function s(i,t,p,r,c,l){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="_1-为什么是-uni-app" tabindex="-1">1. 为什么是 uni-app <a class="header-anchor" href="#_1-为什么是-uni-app" aria-label="Permalink to &quot;1. 为什么是 uni-app&quot;">​</a></h1><h2 id="一个具体的场面" tabindex="-1">一个具体的场面 <a class="header-anchor" href="#一个具体的场面" aria-label="Permalink to &quot;一个具体的场面&quot;">​</a></h2><p>管理端上线了。你兴冲冲把地址发到班群，配了一句“同学们可以在上面报名了”。</p><p>十分钟后，群里陆续冒出这些话：</p><ul><li>“在哪儿点啊，字好小”</li><li>“我手机上打开了，按钮点不到”</li><li>“要注册吗？我懒得注册”</li><li>“能不能直接发个二维码，扫一下就报名的”</li></ul><p>你打开手机看了下自己做的页面：表格横向溢出，侧边栏占了半屏，按钮得放大三倍才点得到。<strong>这个界面从设计的那天起就不是给手机用的。</strong></p><p>于是问题变成：<strong>学生这一端，用什么做？</strong></p><h2 id="三条路-选哪条" tabindex="-1">三条路，选哪条 <a class="header-anchor" href="#三条路-选哪条" aria-label="Permalink to &quot;三条路，选哪条&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>给管理端加媒体查询，做成响应式</td><td>不用写新代码</td><td>桌面后台的表格、侧边栏、弹窗在手机上很难改造，改完两边都别扭</td></tr><tr><td>单独写一个手机版 Web</td><td>完全自由</td><td>学生还是得每次输网址或收藏；发布一个 H5 也要自己处理各种浏览器差异</td></tr><tr><td><strong>用 uni-app 写，编译成多端</strong></td><td>一套代码出 H5、小程序、App</td><td>要学一套新的页面配置与 API 用法，部分 Web 写法在端上不可用</td></tr></tbody></table><p>我们选第三条。理由不是“多端听起来厉害”，而是小程序这个入口的学习成本最低 —— <strong>学生扫码就能用，不用注册账号、不用记网址、不用装 App。</strong></p><h2 id="uni-app-是怎么做到一套代码多端的" tabindex="-1">uni-app 是怎么做到一套代码多端的 <a class="header-anchor" href="#uni-app-是怎么做到一套代码多端的" aria-label="Permalink to &quot;uni-app 是怎么做到一套代码多端的&quot;">​</a></h2><p>关键要理解一件事：<strong>uni-app 不是运行时，是编译器。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的代码（Vue 3 单文件组件 + uni 的 API）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   uni-app 编译器（在你机器上跑）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span> ┌──────────┬──────────┬──────────┬──────────┐</span></span>
<span class="line"><span> │  H5      │ 微信小程序 │ 支付宝小程序│  App     │</span></span>
<span class="line"><span> │ HTML+css │ wxml+wxss│ axml+acss│ 原生渲染   │</span></span>
<span class="line"><span> └──────────┴──────────┴──────────┴──────────┘</span></span></code></pre></div><p>编译期就完成了转换，所以：</p><ul><li>你写的 <code>&lt;view&gt;</code> 在小程序里变成 <code>wxml</code> 的 <code>view</code> 标签，在 H5 里变成 <code>&lt;div&gt;</code></li><li>你写的 <code>uni.request()</code> 在小程序里调用 <code>wx.request</code>，在 H5 里用 <code>XMLHttpRequest</code></li><li>你写的样式会被转成各平台认识的形式</li></ul><p><strong>这也解释了后面所有“为什么不行”的问题。</strong> 凡是编译期无法转换的东西都不能用 —— DOM 操作、<code>window</code> 对象、浏览器专有 API，都是这个道理。</p><h2 id="先分清-uni-app-和-uni-app-x-是两个东西" tabindex="-1">先分清：uni-app 和 uni-app x 是两个东西 <a class="header-anchor" href="#先分清-uni-app-和-uni-app-x-是两个东西" aria-label="Permalink to &quot;先分清：uni-app 和 uni-app x 是两个东西&quot;">​</a></h2><p>搜索“uni-app 教程”时，你会同时看到 uni-app 和 uni-app x 这两种说法，容易混。</p><table tabindex="0"><thead><tr><th></th><th>uni-app（经典版）</th><th>uni-app x</th></tr></thead><tbody><tr><td>主语言</td><td>JavaScript / TypeScript</td><td>UTS（带类型约束的语言）</td></tr><tr><td>App 端渲染</td><td>WebView 加原生混合</td><td>原生渲染，没有 WebView</td></tr><tr><td>小程序与 H5</td><td>支持，生态成熟</td><td>不是主攻方向</td></tr><tr><td>样式</td><td>完整 CSS，支持各种选择器</td><td>以 flex 为主，很多高级 CSS 特性不支持</td></tr><tr><td>npm 生态</td><td>绝大多数前端 npm 包可用</td><td>App 端大量 JS 包不可用，要用 UTS 版本</td></tr><tr><td><code>plus</code> 对象</td><td>有，用于调用原生能力</td><td>没有，改用 UTS 直接调系统 API</td></tr><tr><td>组件库</td><td>数量多、成熟</td><td>需要用适配过的 UTS 版本</td></tr><tr><td>适合谁</td><td>项目以小程序、H5 为主</td><td>项目以 App 为主，追求原生性能，需要上架鸿蒙</td></tr></tbody></table><p><strong>这门课用经典版。</strong> 三个理由：</p><ol><li>我们的目标是 H5 加微信小程序，这正是经典版的强项</li><li>教学要能在浏览器里直接看到结果，uni-app x 的调试链路更长</li><li>经典版用的还是 JavaScript 和 Vue 3 那套东西，<strong>你在前 10 个单元学到的东西全部作数</strong></li></ol><div class="warning custom-block"><p class="custom-block-title">别在项目里混用</p><p>两个版本的项目结构看着像，但底层完全不同。<strong>不要把经典版的项目直接当 uni-app x 项目打开</strong>，也不要在教程里跳着用两边的写法。这一栏从头到尾只说经典版（下文提到“uni-app”都指经典版）。</p></div><h2 id="和管理端的-vue-项目差在哪" tabindex="-1">和管理端的 Vue 项目差在哪 <a class="header-anchor" href="#和管理端的-vue-项目差在哪" aria-label="Permalink to &quot;和管理端的 Vue 项目差在哪&quot;">​</a></h2><p>这是最该记住的一张表。<strong>左边你都会，右边是新东西。</strong></p><table tabindex="0"><thead><tr><th>项</th><th>管理端（Vue 3 Web）</th><th>用户端（uni-app）</th></tr></thead><tbody><tr><td>工程入口</td><td><code>index.html</code> + <code>main.js</code></td><td><code>main.js</code> 导出 <code>createApp</code>，入口由编译器生成</td></tr><tr><td>页面注册</td><td>路由表写在 <code>router/index.js</code></td><td>页面写在 <code>pages.json</code> 的数组里</td></tr><tr><td>路由跳转</td><td><code>router.push(&#39;/activity/1&#39;)</code></td><td><code>uni.navigateTo({ url: &#39;/pages/activity/detail?id=1&#39; })</code></td></tr><tr><td>路由守卫</td><td><code>router.beforeEach</code></td><td>没有全局守卫，用页面生命周期或 <code>uni.addInterceptor</code></td></tr><tr><td>根元素</td><td>组件可以多根</td><td>页面必须能落到 <code>view</code> 等内置组件上</td></tr><tr><td>DOM 操作</td><td><code>document.querySelector</code> 随便用</td><td><strong>没有 <code>document</code>，也没有 <code>window</code></strong></td></tr><tr><td>本地存储</td><td><code>localStorage</code></td><td><code>uni.setStorageSync</code> / <code>uni.getStorageSync</code></td></tr><tr><td>网络请求</td><td><code>axios</code></td><td><code>uni.request</code>（回调式，要自己包成 Promise）</td></tr><tr><td>样式单位</td><td><code>px</code> / <code>rem</code></td><td><code>rpx</code>（750rpx 等于屏幕宽度）</td></tr><tr><td>点击事件</td><td><code>@click</code></td><td><code>@click</code> 也行，但官方推荐 <code>@tap</code></td></tr><tr><td>页面生命周期</td><td><code>onMounted</code> / <code>onUnmounted</code></td><td>额外有 <code>onLoad</code> / <code>onShow</code> / <code>onPullDownRefresh</code> / <code>onReachBottom</code></td></tr><tr><td>生命周期导入</td><td>从 <code>vue</code> 导入</td><td>页面钩子从 <code>@dcloudio/uni-app</code> 导入</td></tr><tr><td>富文本</td><td><code>v-html</code></td><td><code>&lt;rich-text :nodes=&quot;html&quot; /&gt;</code></td></tr><tr><td>页面跳转传参</td><td>路由参数，任意对象</td><td>URL 查询串，只能传字符串</td></tr></tbody></table><p><strong>最需要当心的是第四行和第五行。</strong> 你在管理端习惯的 <code>document</code>、<code>window</code>、<code>localStorage</code>、<code>axios</code>，在小程序里一个都不存在。编译不会报错到让你一眼看出问题，而是运行时白屏或者报 <code>document is not defined</code>。</p><h2 id="什么时候不该用-uni-app" tabindex="-1">什么时候不该用 uni-app <a class="header-anchor" href="#什么时候不该用-uni-app" aria-label="Permalink to &quot;什么时候不该用 uni-app&quot;">​</a></h2><p>工具没有绝对的好坏，说清适用边界：</p><table tabindex="0"><thead><tr><th>场景</th><th>该不该用</th></tr></thead><tbody><tr><td>要出微信小程序</td><td>用，这就是它的主场</td></tr><tr><td>要出手机 App 且能接受 WebView 性能</td><td>用</td></tr><tr><td>要出手机 App 且追求原生流畅度、要上架鸿蒙</td><td>看 uni-app x，或者直接原生</td></tr><tr><td>只在浏览器里跑的桌面管理后台</td><td>不要用。选 Element Plus 那套更省事</td></tr><tr><td>需要大量操作 DOM、和第三方 JS 库深度集成</td><td>慎用。小程序环境不给你 DOM</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>uni-app 是<strong>编译器</strong>，不是运行时，一套代码在编译期分别转成各平台的产物</li><li>经典版和 uni-app x 是两套技术，<strong>这门课用经典版</strong>：Vue 3 + JS，主攻 H5 与小程序</li><li>与管理端最大的差异在四处：<strong>路由变成配置、没有 DOM、请求换成 <code>uni.request</code>、单位换成 rpx</strong></li><li>编辑器的自动补全帮不了你识别“这个 API 在小程序里没有”，<strong>要靠你自己记住哪些写法不能用</strong></li><li>工具链版本比管理端旧，这是跨端框架的固有代价，不是写错了</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><details class="details custom-block"><summary>装了浏览器插件试 uni-app，结果什么都没看到</summary><p><strong>现象：</strong> 在浏览器里直接打开 <code>src/pages/index/index.vue</code>，页面一片空白。</p><p><strong>原因：</strong> <code>.vue</code> 文件不是浏览器能直接执行的东西，它必须经过 uni-app 编译器处理。管理端的 Vite 项目也一样，只是你习惯了在 <code>localhost</code> 上通过开发服务器看，忘了这一步。</p><p><strong>怎么处理：</strong> 永远通过 <code>pnpm dev:h5</code> 启动的开发服务器访问，不要直接双击文件。记住这条，后面也就不会再犯。</p></details><details class="details custom-block"><summary>在脚本里用了 <code>window.localStorage</code>，小程序端报错</summary><p><strong>现象：</strong> H5 端一切正常，切到微信小程序后白屏，控制台报 <code>window is not defined</code> 或者 <code>localStorage is not defined</code>。</p><p><strong>原因：</strong> 小程序的运行环境里没有浏览器对象模型，<code>window</code>、<code>document</code>、<code>localStorage</code>、<code>navigator</code> 都不存在。H5 端有，所以问题只在某一端暴露 —— <strong>这也是为什么两个端都要跑一遍，不能只看 H5 通过就提交。</strong></p><p><strong>怎么处理：</strong> 换成 uni 的 API：<code>uni.setStorageSync()</code> / <code>uni.getStorageSync()</code>。如果确实需要一段只在 H5 生效的代码，用条件编译把它圈起来：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// #ifdef H5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">someThirdPartyThing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// #endif</span></span></code></pre></div></details><details class="details custom-block"><summary>搜到的 uni-app 教程是用 <code>new Vue()</code> 写的</summary><p><strong>现象：</strong> 照着搜索到的文章写，代码里出现 <code>new Vue({ el: &#39;#app&#39; })</code>、<code>Vue.use(...)</code>、<code>this.$refs.xxx</code>，项目跑不起来。</p><p><strong>原因：</strong> 网上大量 uni-app 文章是 2020 年前后写的，那时候默认是 Vue 2。<strong>搜索结果不会告诉你它过期了。</strong></p><p><strong>怎么处理：</strong> 看文档只认官方地址 <code>uniapp.dcloud.net.cn</code>，并确认页面上的“Vue 3”标识。判断一段代码是不是 Vue 2 写法，看有没有这些特征：<code>new Vue()</code>、<code>Vue.prototype</code>、<code>this.$set</code>、选项式里的 <code>data()</code> 返回对象、<code>beforeDestroy</code> 生命周期名。<strong>碰到就丢掉换一篇。</strong></p></details><h2 id="课后练习" tabindex="-1">课后练习 <a class="header-anchor" href="#课后练习" aria-label="Permalink to &quot;课后练习&quot;">​</a></h2><p>拿管理端的一个页面对照一遍，<strong>只做纸上分析，不写代码</strong>。</p><p>任选一个页面（推荐选活动列表页，它的元素最多），完成下面这张对照表：</p><table tabindex="0"><thead><tr><th>管理端用到的写法</th><th>在用户端换成什么</th><th>属于哪一类问题</th></tr></thead><tbody><tr><td>例：<code>router.push(&#39;/activity/&#39; + id)</code></td><td><code>uni.navigateTo({ url: &#39;/pages/activity/detail?id=&#39; + id })</code></td><td>路由方式不同</td></tr><tr><td>例：<code>localStorage.setItem(&#39;token&#39;, t)</code></td><td><code>uni.setStorageSync(&#39;token&#39;, t)</code></td><td>没有浏览器对象</td></tr><tr><td>例：<code>&lt;el-table&gt;</code></td><td>换成列表卡片，没有等价组件</td><td>桌面组件不适合触屏</td></tr><tr><td></td><td></td><td></td></tr></tbody></table><p>表格要求写满 8 行，<strong>其中至少 2 行是“用户端没有等价写法，要换一种设计”</strong>，而不是简单换 API 名字。</p><details class="details custom-block"><summary>验收标准与参考思路</summary><p><strong>验收标准：</strong></p><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>行数</td><td>不少于 8 行</td></tr><tr><td>分类</td><td>每行标注属于哪一类：路由方式、浏览器对象、单位换算、组件不可用、请求方式、生命周期</td></tr><tr><td>至少有 2 行</td><td>属于“没有等价写法，要改设计”，并说明改成什么设计</td></tr><tr><td>结论</td><td>最后写两三句：这个页面照搬到手机上，最别扭的是哪一处</td></tr></tbody></table><p><strong>不合格的写法：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| 用了 px | 改成 rpx | 单位换算 |</span></span></code></pre></div><p>只写“改成 rpx”等于没分析。真实情况是：表格的列宽在手机上无论如何都摆不下，你得决定显示哪几列、剩下的挪到详情页 —— <strong>这是设计问题，不是换算问题。</strong></p><p><strong>合格的写法：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| \`&lt;el-table&gt;\` 的 6 列布局 | 手机上摆不下 6 列，改成卡片列表：只显示标题、类型标签、报名进度；其余字段放详情页 | 组件不可用，要改设计 |</span></span>
<span class="line"><span>| 表格的“操作”列放 4 个按钮 | 改成卡片底部的 1 到 2 个主按钮，其余收进“更多”菜单 | 触屏点击区不够，要改设计 |</span></span>
<span class="line"><span>| \`el-pagination\` 分页 | 换成触底自动加载下一页 | 手机上不该让人点页码 |</span></span></code></pre></div><p><strong>参考思路：</strong> 拿活动列表页分析，通常能凑出这些条目 —— 路由跳转、分页组件、表格组件、<code>px</code> 单位、<code>localStorage</code> 存 token、<code>axios</code> 请求、<code>document</code> 相关的第三方库、<code>el-message</code> 提示、<code>onMounted</code> 里发请求（用户端要在 <code>onLoad</code> 里发）、日期格式化库（有些依赖 <code>Intl</code>，小程序支持情况不一）。<strong>其中“要改设计”的至少有分页、表格、操作列这三处。</strong></p></details><hr><p>上一节：<a href="/frontend-engineering-course/mobile/">用户端总览</a> · 下一节：<a href="/frontend-engineering-course/mobile/02-scaffold.html">建工程：从命令到跑起来</a></p>`,43)])])}const g=e(n,[["render",s]]);export{h as __pageData,g as default};
